def solve(g):
    H,W=len(g),len(g[0]); bg=g[0][0]
    from collections import Counter
    cnt=Counter(x for r in g for x in r if x!=bg)
    cells={col:set((r,c) for r in range(H) for c in range(W) if g[r][c]==col) for col in cnt}
    markcol=[col for col in cnt if not any((r+1,c) in cells[col] or (r,c+1) in cells[col] for r,c in cells[col])][0]
    pat=[(r,c) for col in cnt if col!=markcol for (r,c) in cells[col]]
    markers=list(cells[markcol])
    out=[row[:] for row in g]
    for r,c in markers: out[r][c]=bg
    rs=[r for r,_ in pat]; cs=[c for _,c in pat]
    if max(cs)-min(cs)>=max(rs)-min(rs):
        c0=min(cs); anchor=c0+(max(cs)-c0)//2
        for r,c in markers:
            s=c-(anchor-c0)
            for cc in range(c0,max(cs)+1):
                if 0<=s+(cc-c0)<W: out[r][s+(cc-c0)]=g[pat[0][0]][cc]
    else:
        r0=min(rs); anchor=r0+(max(rs)-r0)//2
        cc0=pat[0][1]
        for r,c in markers:
            s=r-(anchor-r0)
            for rr in range(r0,max(rs)+1):
                if 0<=s+(rr-r0)<H: out[s+(rr-r0)][c]=g[rr][cc0]
    return out

